// Returns each item's `n`, uppercased when `a == 1`. Skips null/undefined items.
function proc(items) {
  return items
    .filter((item) => item != null)
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

// Splits a comma-separated string into trimmed, non-empty parts.
function f2(text) {
  return text
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part !== '');
}

module.exports = { proc, f2 };

